package org.sleepwell.app;
import android.app.*;import android.content.Intent;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
/** Private repeat-rule draft. Only Use returns it; the parent still requires Save alarm. */
public final class AlarmRepeatActivity extends Activity {
 static final int REQUEST=839;private Alarm alarm;private String request,identity,error="",every="3";private AlarmRepeat.Mode mode;private LocalDate anchor;private final Set<Integer> days=new TreeSet<>();private EditText interval;private TextView projection,validation;private RecordCalendar calendar;private Dialog details;
 static Intent edit(Activity owner,Alarm alarm,String request){return RecordUi.intent(owner,AlarmRepeatActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("request",request);}
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);setResult(RESULT_CANCELED);try{request=getIntent().getStringExtra("request");if(!BackupRuntime.nonce(request))throw new IllegalArgumentException();alarm=Alarm.read(new JSONObject(getIntent().getStringExtra("alarm")));if(alarm.nap!=null||alarm.napInvalid)throw new IllegalArgumentException();identity=AlarmRepeat.identity(alarm);mode=state==null?alarm.repeatRule.mode:AlarmRepeat.Mode.valueOf(state.getString("mode"));anchor=state==null?(alarm.repeatRule.anchor==null?LocalDate.now():alarm.repeatRule.anchor):LocalDate.parse(state.getString("anchor"));every=state==null?Integer.toString(alarm.repeatRule.every==0?3:alarm.repeatRule.every):state.getString("every","3");days.addAll(state==null?alarm.days:AlarmRepeat.days(new JSONArray(state.getString("days","[]"))));error=state==null?(alarm.repeatInvalid?"Saved repeat settings need review. Choose a rule before using it.":""):state.getString("error","");}catch(Exception invalid){finish();return;}render();if(state!=null&&state.containsKey("calendar"))openAnchor(state.getBundle("calendar"));}
 private void keepInput(){if(interval!=null)every=interval.getText().toString();}
 private Alarm candidate()throws JSONException{Alarm copy=Alarm.read(alarm.json());AlarmRepeat rule=mode==AlarmRepeat.Mode.WEEKLY?AlarmRepeat.WEEKLY:mode==AlarmRepeat.Mode.INTERVAL?new AlarmRepeat(mode,intervalValue(),anchor):new AlarmRepeat(mode,0,null);copy.setRepeat(rule);copy.days=new HashSet<>(mode==AlarmRepeat.Mode.INTERVAL?AlarmRepeat.ALL:days);if(copy.date!=null&&!copy.days.isEmpty())throw new IllegalArgumentException("Clear the one-time Run on date before choosing repeat days.");rule.check(copy);if(!AlarmSkips.scheduleKey(copy).equals(AlarmSkips.scheduleKey(alarm)))AlarmSkips.consume(copy);return copy;}
 private int intervalValue(){try{int value=Integer.parseInt(every);if(value<1||value>365)throw new NumberFormatException();return value;}catch(NumberFormatException invalid){throw new IllegalArgumentException("Choose an interval from 1 to 365 days.");}}
 private void render(){
  keepInput();interval=null;projection=null;validation=null;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);
  RecordUi.menuAction(RecordUi.header(body,"Repeat rule",this::finish),"Repeat rule options",this::about,false);Design.space(body,14);
  RecordUi.segments(body,new String[]{"Weekly","Odd weeks","Even weeks","Interval"},mode.ordinal(),n->{keepInput();mode=AlarmRepeat.Mode.values()[n];error="";render();});Design.space(body,20);
  Design.text(body,switch(mode){case WEEKLY->"Repeat on";case ODD->"Odd ISO weeks";case EVEN->"Even ISO weeks";case INTERVAL->"Repeat every";},23,600,Design.INK);Design.space(body,8);
  if(mode==AlarmRepeat.Mode.INTERVAL){
   Design.text(body,"Count calendar days from your start date.",14,400,Design.MUTED);Design.space(body,16);
   LinearLayout number=Design.row(this);number.addView(stepButton("minus","Decrease interval",-1),new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));
   interval=new EditText(this);interval.setContentDescription("Repeat interval days");interval.setSingleLine(true);interval.setSelectAllOnFocus(true);interval.setInputType(InputType.TYPE_CLASS_NUMBER);interval.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(3)});interval.setText(every);interval.setTextSize(30*Appearance.scale(this));interval.setTypeface(Design.font(this,600));interval.setTextColor(Design.INK);interval.setGravity(Gravity.CENTER);Design.pad(interval,12,12);interval.setBackground(Design.outline(this,Design.SOFT,Design.LINE,14));LinearLayout.LayoutParams inputBounds=new LinearLayout.LayoutParams(0,-2,1);inputBounds.leftMargin=Design.dp(this,12);inputBounds.rightMargin=Design.dp(this,12);number.addView(interval,inputBounds);
   number.addView(stepButton("plus","Increase interval",1),new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(number);Design.space(body,6);Design.text(body,"Days · 1–365",12,400,Design.MUTED).setGravity(Gravity.CENTER);Design.space(body,14);
   Design.item(body,"calendar","Start date",anchor.toString(),()->openAnchor(null));Design.line(body);
   interval.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){every=s.toString();updateProjection();}public void afterTextChanged(android.text.Editable text){}});
  }else{
   Design.text(body,mode==AlarmRepeat.Mode.WEEKLY?"Leave all days off for a one-time alarm.":"Choose weekdays on "+(mode==AlarmRepeat.Mode.ODD?"odd":"even")+"-numbered ISO weeks.",14,400,Design.MUTED);Design.space(body,16);
   LinearLayout week=Design.row(this);String[] labels={"M","T","W","T","F","S","S"},names={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};
   for(int n=1;n<=7;n++){int day=n;Button button=dayButton(labels[n-1],days.contains(n),()->{keepInput();if(days.contains(day))days.remove(day);else days.add(day);error="";render();});button.setContentDescription(names[n-1]);button.setSelected(days.contains(n));LinearLayout.LayoutParams bounds=new LinearLayout.LayoutParams(0,Design.dp(this,48),1);bounds.setMargins(Design.dp(this,1),0,Design.dp(this,1),0);week.addView(button,bounds);}body.addView(week);
  }
  Design.space(body,22);LinearLayout preview=Design.col(this);Design.pad(preview,16,16);preview.setBackground(Design.shape(this,Design.SOFT,16));Design.text(preview,"Next alarm from this rule",13,500,Design.MUTED);Design.space(preview,8);projection=Design.text(preview,"",16,600,Design.INK);body.addView(preview);updateProjection();
  Design.space(body,12);Design.text(body,"Time zone · "+ZoneId.systemDefault().getId(),12,400,Design.MUTED);
  LinearLayout footer=RecordUi.footer(body);validation=Design.text(footer,error,13,500,NightDialTokens.NEGATIVE);validation.setContentDescription("Repeat validation message");validation.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);validation.setVisibility(error.isEmpty()?View.GONE:View.VISIBLE);Design.space(footer,8);Design.text(footer,"Save alarm applies this repeat rule.",12,400,Design.MUTED);Design.space(footer,6);Design.button(footer,"Use repeat rule",true,this::use);Design.button(footer,"Cancel",false,this::finish);
 }
 private View stepButton(String icon,String label,int direction){View button=Design.iconButton(this,icon,label,()->{keepInput();int current;try{current=Integer.parseInt(every);}catch(NumberFormatException invalid){current=1;}String next=Integer.toString(Math.max(1,Math.min(365,current+direction)));if(interval!=null)interval.setText(next);else every=next;error="";render();});button.setBackground(Design.touch(this,Design.SOFT,14));return button;}
 private void updateProjection(){if(projection==null)return;try{keepInput();Alarm proposed=candidate();long at=proposed.next(System.currentTimeMillis(),ZoneId.systemDefault());projection.setText(at>0?RecordUi.date(at,ZoneId.systemDefault())+" · "+RecordUi.clock(this,at,ZoneId.systemDefault()):"No future occurrence. Review the date and exclusions.");if(validation!=null){error="";validation.setText("");validation.setVisibility(View.GONE);}}catch(Exception invalid){String message=invalid.getMessage()==null?"Review the selected days and interval.":invalid.getMessage();projection.setText(message);if(validation!=null&&!error.isEmpty()){error=message;validation.setText(message);validation.setVisibility(View.VISIBLE);}}}
 private void about(){keepInput();if(details!=null)details.dismiss();details=SleepPicker.message(this,"How repeat rules work","Weekly with no selected days means one ordinary occurrence. Odd and Even use ISO weeks, which start on Monday. Week 1 has at least four days in the new year; weeks 53 and 1 can both be odd.\n\nAn interval counts calendar days from its start date, including that date. Earlier dates and weekday filters do not apply.\n\nDates use "+ZoneId.systemDefault().getId()+" and the alarm’s existing daylight-saving rules. Sunrise alarms keep their calculated time and fallback. Calendar adjustments and selected days off apply when you Save alarm. Current snoozes and ringing alarms stay unchanged.");}
 private Button dayButton(String label,boolean selected,Runnable action){Button button=new Button(this);button.setStateListAnimator(null);button.setElevation(0);button.setText(label);button.setAllCaps(false);button.setTextSize(15*Appearance.scale(this));button.setTypeface(Design.font(this,600));button.setPadding(0,0,0,0);button.setMinWidth(0);button.setMinimumWidth(0);button.setTextColor(selected?Design.CREAM:Design.BROWN);button.setBackground(Design.touch(this,selected?Design.BROWN:Design.SOFT,24));button.setAccessibilityDelegate(new View.AccessibilityDelegate(){@Override public void onInitializeAccessibilityNodeInfo(View host,android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(host,info);info.setClassName(CheckBox.class.getName());info.setCheckable(true);info.setChecked(selected);}});button.setOnClickListener(view->{InteractionFeedback.selection(view);action.run();});return button;}
 private void use(){if(!hasWindowFocus())return;keepInput();try{Alarm selected=candidate();setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("draft",identity).putExtra("rule",AlarmRepeat.encode(selected.repeatRule).toString()).putExtra("days",new JSONArray(new TreeSet<>(selected.days)).toString()));finish();}catch(Exception invalid){error=invalid.getMessage()==null?"Choose a valid repeat rule.":invalid.getMessage();render();}}
 private void openAnchor(Bundle restored){keepInput();if(calendar!=null)calendar.close();calendar=new RecordCalendar(this,"Repeat anchor date",anchor,restored,date->{if(date.getYear()<1970||date.getYear()>9998)error="Choose an anchor year from 1970 to 9998.";else{anchor=date;error="";}render();},null);}
 @Override public void onSaveInstanceState(Bundle state){keepInput();super.onSaveInstanceState(state);state.putString("mode",mode.name());state.putString("anchor",anchor.toString());state.putString("every",every);state.putString("days",new JSONArray(days).toString());state.putString("error",error);if(calendar!=null&&calendar.showing())state.putBundle("calendar",calendar.state());}
 @Override protected void onDestroy(){if(calendar!=null)calendar.close();if(details!=null)details.dismiss();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
